'use client';

import * as React from 'react';
import {createComponent} from '@lit/react';
import '@material/web/labs/gb/components/carousel/md-gb-carousel.js';
import '@material/web/labs/gb/components/carousel/md-gb-carousel-item.js';
import {CarouselElement} from '@material/web/labs/gb/components/carousel/carousel-element.js';
import {CarouselItemElement} from '@material/web/labs/gb/components/carousel/carousel-item-element.js';

/**
 * A Material Design carousel. Wraps <md-gb-carousel>.
 * Docs: https://material-web.dev/3.0/components/carousel/
 */
export const MdCarousel = createComponent({
  react: React,
  tagName: 'md-gb-carousel',
  elementClass: CarouselElement,
});

export type MdCarouselProps = React.ComponentProps<typeof MdCarousel>;

/**
 * A Material Design carousel item. Wraps <md-gb-carousel-item>.
 * Docs: https://material-web.dev/3.0/components/carousel/
 */
export const MdCarouselItem = createComponent({
  react: React,
  tagName: 'md-gb-carousel-item',
  elementClass: CarouselItemElement,
});

export type MdCarouselItemProps = React.ComponentProps<typeof MdCarouselItem>;
